// Generated by `hdr install opencode`. Reinstall rather than edit: HDR checks
// this file byte for byte and reports any other content as an unregistered hook.
import assert from "node:assert"
import { spawnSync } from "node:child_process"

const COMMAND = __HDR_COMMAND__

function runChecker(payload) {
  assert(payload.hook_event_name && payload.session_id, "HDR payload needs an event and session")
  const run = spawnSync(COMMAND[0], COMMAND.slice(1), {
    input: JSON.stringify(payload),
    encoding: "utf8",
    timeout: 15000,
  })
  if (run.error || run.status !== 0) {
    // Fail closed: a checker that cannot run must not silently allow tool calls.
    return { deny: `HDR ERROR: ${run.stderr || run.error}` }
  }
  const out = run.stdout.trim() ? JSON.parse(run.stdout) : {}
  const specific = out.hookSpecificOutput || {}
  assert(typeof out === "object", `HDR returned non-object output: ${run.stdout}`)
  return {
    deny: specific.permissionDecision === "deny" ? specific.permissionDecisionReason : undefined,
    block: out.decision === "block" ? out.reason : undefined,
    message: out.systemMessage,
  }
}

export const HdrPlugin = async ({ directory, client }) => {
  assert(directory, "opencode did not provide a project directory")
  assert(client, "opencode did not provide an SDK client")
  const base = (name, session) => {
    assert(session, `HDR ${name} event has no session ID`)
    const payload = { hook_event_name: name, session_id: session, cwd: directory }
    assert(payload.cwd === directory, "HDR payload lost its directory")
    return payload
  }
  const warn = async (message) => {
    assert(typeof message === "string", "HDR warning must be text")
    try {
      await client.tui.showToast({ body: { message, variant: "warning" } })
    } catch (error) {
      console.error("HDR warning", { message, error: String(error) })
    }
    assert(message.length > 0, `HDR warning must not be empty (length=${message.length})`)
  }
  return {
    event: async ({ event }) => {
      if (event.type === "session.created") {
        const session = event.properties.info
        const result = runChecker({ ...base("SessionStart", session.id), source: "startup" })
        if (result.message && !result.message.startsWith("HDR PASS")) await warn(result.message)
      }
      if (event.type === "session.idle") {
        // opencode cannot resume an idle session from a plugin, so Stop failures only warn.
        const result = runChecker(base("Stop", event.properties.sessionID))
        if (result.block) await warn(result.block)
      }
    },
    "tool.execute.before": async (input, output) => {
      const result = runChecker({
        ...base("PreToolUse", input.sessionID),
        tool_name: input.tool,
        tool_use_id: input.callID,
        tool_input: output.args,
      })
      if (result.deny) throw new Error(result.deny)
    },
    "tool.execute.after": async (input, output) => {
      const result = runChecker({
        ...base("PostToolUse", input.sessionID),
        tool_name: input.tool,
        tool_use_id: input.callID,
        tool_input: input.args,
      })
      if (result.block) output.output = `${output.output}\n\n${result.block}`
    },
  }
}
